/* From Uiverse.io by andrew-demchenk0 - Tags: red, checkbox, like, heart */
.__UIV_SCOPE__ .container input {
  position: absolute;
  opacity: 0;
  cursor: pointer;
  height: 0;
  width: 0;
}

.__UIV_SCOPE__ .container {
  display: block;
  position: relative;
  cursor: pointer;
  user-select: none;
}

.__UIV_SCOPE__ .container svg {
  position: relative;
  top: 0;
  left: 0;
  height: 50px;
  width: 50px;
  transition: all 0.3s;
  fill: #666;
}

.__UIV_SCOPE__ .container svg:hover {
  transform: scale(1.1);
}

.__UIV_SCOPE__ .container input:checked ~ svg {
  fill: #E3474F;
}
